curl -L --max-time 20 -sS http://127.0.0.1:8000/content/python-best-practices-page | python -c 'import sys; from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.out=[]; self.skip=0
 def handle_starttag(self,t,a):
  if t in ("script","style","noscript"): self.skip+=1
  if not self.skip and t in ("h1","h2","h3","h4","p","li","pre","code","title"): self.out.append("\n["+t+"] ")
 def handle_endtag(self,t):
  if t in ("script","style","noscript"): self.skip=max(0,self.skip-1)
 def handle_data(self,d):
  if not self.skip and d.strip(): self.out.append(d)
p=P(); p.feed(sys.stdin.read()); print("".join(p.out))'

